namespace NatureFX.Tools {
	public static class SettingsMeta {
		// the debug page's settings texts, English and Japanese: /meta.json
		public const string Json = @"{""en"":{""settings"":{""NativeSky"":{""label"":""Native sky"",""help"":""map extension (docs/map-authoring.md 5 and 7): season of the foliage colours and the floating particles (0 automatic: the weather preset, else the map's [defaults] season; 1 spring .. 4 winter; 5 none), the 3D grass (density multiplier, metres from the camera) and the map's decals, water, local fog and particles leaves and grass brought to measured colours (0 the textures' own, 1 a real leaf's: some 4 to 12 % of the light back, an olive green, not a painted one; NFX_LitData) --- added in config version 62: the debug page (Tools/DebugPage.cs) --- sky: HDRP volumetric clouds following the weather (and the map's cloud sea), the strength of their shadows, the blue haze over distant mountains (0 off) the sky drawn by NatureFX's own engine (physically based atmosphere) over HDRP's""},""OwnSkyLighting"":{""label"":""Sky light and reflections from the own engine"",""help"":""HDRP's sky light, sky reflections and sky are switched off; the own engine's GI and reflections give them, blocked by what is around (no open sky in a garage's paint). Each part only while its ray traced pass runs.""},""OwnSunLight"":{""label"":""Sun light from the own engine"",""help"":""HDRP's sun lights nothing; the ray traced shadow pass adds the sun's light (worked out from the G-buffer as HDRP does, or its own where there is none) under the traced shadow. Only while the exact sun light runs (Lighting & shadows).""},""OwnLampLight"":{""label"":""Lamp light from the own engine"",""help"":""HDRP's street lights, headlights and other lamps light nothing; the lamp masks' pass works their light out (cookies included) and the shadow composite adds the share each lamp's traced shadow lets through. Only while the lamp masks run (Lighting & shadows).""},""OwnBrdf"":{""label"":""Own BSDF (no G-buffer copy, experimental)"",""help"":""Experimental: the colour comes from the traced surface, which lacks NatureFX's material work (anti-tiling, build-up, ground blend, paint, detail maps), so such surfaces can show two patterns over each other. The sun and the lamps lit by the own engine's BSDF from the traced surface and HDRP's normals, instead of HDRP's own BSDF from its G-buffer drawn a second time: less video memory and one scene pass fewer. HDRP's material details (subsurface, anisotropy, the paint's flakes) are approximated. Needs the sun and lamp light from the own engine and lamp masks; not with DLSS Ray Reconstruction.""},""OwnTransparentLight"":{""label"":""Light on see-through surfaces"",""help"":""What HDRP draws see-through after the ray traced composite (fences, signs, particles that take light) keeps HDRP's sun and lamps and gets the own engine's sky light: HDRP's lights are put on a rendering layer only those surfaces are on. Off: they get none of it while the own engine lights the rest.""},""Clouds"":{""label"":""Volumetric clouds"",""help"":""map extension (docs/map-authoring.md 5 and 7): season of the foliage colours and the floating particles (0 automatic: the weather preset, else the map's [defaults] season; 1 spring .. 4 winter; 5 none), the 3D grass (density multiplier, metres from the camera) and the map's decals, water, local fog and particles leaves and grass brought to measured colours (0 the textures' own, 1 a real leaf's: some 4 to 12 % of the light back, an olive green, not a painted one; NFX_LitData) --- added in config version 62: the debug page (Tools/DebugPage.cs) --- sky: HDRP volumetric clouds following the weather (and the map's cloud sea), the strength of their shadows, the blue haze over distant mountains (0 off)""},""CloudShadows"":{""label"":""Cloud shadows"",""help"":""map extension (docs/map-authoring.md 5 and 7): season of the foliage colours and the floating particles (0 automatic: the weather preset, else the map's [defaults] season; 1 spring .. 4 winter; 5 none), the 3D grass (density multiplier, metres from the camera) and the map's decals, water, local fog and particles leaves and grass brought to measured colours (0 the textures' own, 1 a real leaf's: some 4 to 12 % of the light back, an olive green, not a painted one; NFX_LitData) --- added in config version 62: the debug page (Tools/DebugPage.cs) --- sky: HDRP volumetric clouds following the weather (and the map's cloud sea), the strength of their shadows, the blue haze over distant mountains (0 off)""},""StarBrightness"":{""label"":""Star brightness"",""help"":""The stars against their physical brightness: the eye's night vision sees far more of them than a camera's exposure.""},""NativeFog"":{""label"":""Native fog"",""help"":""map extension (docs/map-authoring.md 5 and 7): season of the foliage colours and the floating particles (0 automatic: the weather preset, else the map's [defaults] season; 1 spring .. 4 winter; 5 none), the 3D grass (density multiplier, metres from the camera) and the map's decals, water, local fog and particles leaves and grass brought to measured colours (0 the textures' own, 1 a real leaf's: some 4 to 12 % of the light back, an olive green, not a painted one; NFX_LitData) --- added in config version 62: the debug page (Tools/DebugPage.cs) --- sky: HDRP volumetric clouds following the weather (and the map's cloud sea), the strength of their shadows, the blue haze over distant mountains (0 off) the sky drawn by NatureFX's own engine (physically based atmosphere) over HDRP's the fog and haze drawn by the own engine (lit by the traced sun and the engine's sky) instead of HDRP's""},""AerialHaze"":{""label"":""Distant haze"",""help"":""map extension (docs/map-authoring.md 5 and 7): season of the foliage colours and the floating particles (0 automatic: the weather preset, else the map's [defaults] season; 1 spring .. 4 winter; 5 none), the 3D grass (density multiplier, metres from the camera) and the map's decals, water, local fog and particles leaves and grass brought to measured colours (0 the textures' own, 1 a real leaf's: some 4 to 12 % of the light back, an olive green, not a painted one; NFX_LitData) --- added in config version 62: the debug page (Tools/DebugPage.cs) --- sky: HDRP volumetric clouds following the weather (and the map's cloud sea), the strength of their shadows, the blue haze over distant mountains (0 off)""},""HeadlightShafts"":{""label"":""Headlight beams"",""help"":""How much clear air shows the headlights' and lamps' beams (0: not at all; 1: about real clear air). In the weather's fog and the map's fog they show in full.""},""LightShafts"":{""label"":""Sun in the fog"",""help"":""How strongly the sun (and moon) light HDRP's volumetric fog: its shafts between trees and buildings. Needs volumetric fog in the map.""},""NativeLighting"":{""label"":""Native lighting"",""help"":""map extension (docs/map-authoring.md 5 and 7): season of the foliage colours and the floating particles (0 automatic: the weather preset, else the map's [defaults] season; 1 spring .. 4 winter; 5 none), the 3D grass (density multiplier, metres from the camera) and the map's decals, water, local fog and particles leaves and grass brought to measured colours (0 the textures' own, 1 a real leaf's: some 4 to 12 % of the light back, an olive green, not a painted one; NFX_LitData) --- added in config version 62: the debug page (Tools/DebugPage.cs) --- sky: HDRP volumetric clouds following the weather (and the map's cloud sea), the strength of their shadows, the blue haze over distant mountains (0 off) the sky drawn by NatureFX's own engine (physically based atmosphere) over HDRP's the fog and haze drawn by the own engine (lit by the traced sun and the engine's sky) instead of HDRP's all of the opaque lighting from the own engine (roadmap step A): its shadows, lamp shadows, sky light and GI, reflections, whatever the ray tracing toggles say (Rendering.EngineLighting)""},""NativeParticles"":{""label"":""Own particle lighting"",""help"":""roadmap E: the game's own particles drawn with NatureFX/Particle""},""RealisticShadows"":{""label"":""Soft HDRP sun shadows"",""help"":""HDRP's own sun shadows soften with distance from the caster, by Sun size and more under clouds (High shadow filtering). The ray traced shadows have their own softness. Native lighting (Lighting & shadows) is on: this runs whatever the switch below says.""},""SunOverride"":{""label"":""Override sun"",""help"":""sun / time of day (overrides the track's directional light while enabled)""},""SyncGameNight"":{""label"":""The game's night lights"",""help"":""The track's own night lighting (its street lights, lit windows) switches on at dusk and off at dawn of NatureFX's time, as the game does for a night race.""},""TimeOfDay"":{""label"":""Time"",""help"":""hours 0..24""},""TimePasses"":{""label"":""Time passes"",""help"":""The time of day runs on by itself, at the speed below (the slider above follows it).""},""SunAzimuthOffset"":{""label"":""Heading offset"",""help"":""degrees added to the track's sun heading""},""SunMaxElevation"":{""label"":""Max elevation"",""help"":""degrees at noon""},""SunIntensityScale"":{""label"":""Intensity"",""help"":""sun / time of day (overrides the track's directional light while enabled)""},""SunTemperature"":{""label"":""Colour temperature"",""help"":""kelvin at noon (warmer near the horizon)""},""Moonlight"":{""label"":""Moonlight at night"",""help"":""weather & environment""},""Wind"":{""label"":""Enable"",""help"":""nature""},""WindStrength"":{""label"":""Strength"",""help"":""nature""},""WindGust"":{""label"":""Gusts"",""help"":""nature""},""WindDirection"":{""label"":""Direction"",""help"":""nature""},""LeafFlutter"":{""label"":""Leaf flutter"",""help"":""nature""},""FoliageSway"":{""label"":""Foliage sway"",""help"":""--- added in config version 2 ---""},""InteractiveFoliage"":{""label"":""Cars push grass"",""help"":""nature""},""Accumulation"":{""label"":""Enable"",""help"":""accumulation / weather""},""WeatherPreset"":{""label"":""Weather"",""help"":""see WeatherController.Presets""},""WeatherCycle"":{""label"":""Changing weather"",""help"":""Moves between clear, cloudy, rain, fog... on its own.""},""WeatherCycleMinutes"":{""label"":""Change every"",""help"":""weather & environment""},""CloudAmount"":{""label"":""Clouds"",""help"":""The clouds with the Clear and Manual weather: 0 a clear sky with a few fair weather clouds, 0.5 half covered, 1 overcast. Manual rain closes the sky over at least as far as it needs.""},""WeatherChangeTime"":{""label"":""Change time"",""help"":""How long a change of weather takes, the clouds included.""},""Season"":{""label"":""Season"",""help"":""map extension (docs/map-authoring.md 5 and 7): season of the foliage colours and the floating particles (0 automatic: the weather preset, else the map's [defaults] season; 1 spring .. 4 winter; 5 none), the 3D grass (density multiplier, metres from the camera) and the map's decals, water, local fog and particles""},""FoliageColor"":{""label"":""Real leaf colour"",""help"":""1: leaves and grass as dark and olive as real ones (a leaf sends back some 4 to 12 % of the light). 0: the textures' own colours.""},""Precipitation"":{""label"":""Precipitation"",""help"":""map extension (docs/map-authoring.md 5 and 7): season of the foliage colours and the floating particles (0 automatic: the weather preset, else the map's [defaults] season; 1 spring .. 4 winter; 5 none), the 3D grass (density multiplier, metres from the camera) and the map's decals, water, local fog and particles leaves and grass brought to measured colours (0 the textures' own, 1 a real leaf's: some 4 to 12 % of the light back, an olive green, not a painted one; NFX_LitData) --- added in config version 62: the debug page (Tools/DebugPage.cs) --- sky: HDRP volumetric clouds following the weather (and the map's cloud sea), the strength of their shadows, the blue haze over distant mountains (0 off) the sky drawn by NatureFX's own engine (physically based atmosphere) over HDRP's